<?= $this->extend('layouts/app') ?><?= $this->section('content') ?>
<div class="page-head"><div><h1>Sports</h1><p>Manage sport categories and scoring types for the active event.</p></div><button class="btn primary" data-modal="sport-modal" <?= !$activeEvent ? 'disabled' : '' ?>><?= ui_icon('plus') ?><span>Add Sport</span></button></div>
