<?php foreach ($sports as $sport): ?><dialog id="sport-edit-<?= (int) $sport['id'] ?>"><form method="post" action="<?= site_url('sports/'.$sport['id'].'/update') ?>" class="modal-card"><?= csrf_field() ?><div class="modal-head"><h2>Edit Sport</h2><button type="button" data-close aria-label="Close"><?= ui_icon('x') ?></button></div><label>Category<select name="category" required><?php foreach (['Men','Women','Mixed'] as $category): ?><option value="<?= $category ?>" <?= $sport['category'] === $category ? 'selected' : '' ?>><?= $category ?></option><?php endforeach; ?></select></label><label>Sport Name<input name="name" required maxlength="120" value="<?= esc($sport['name']) ?>"></label><label>Sport Type<select name="result_type" required><option value="match" <?= $sport['result_type'] === 'match' ? 'selected' : '' ?>>Match</option><option value="judged" <?= $sport['result_type'] === 'judged' ? 'selected' : '' ?>>Judged</option></select></label><button class="btn primary full"><?= ui_icon('save') ?><span>Save Changes</span></button></form></dialog><?php endforeach; ?>
<dialog id="sport-modal"><form method="post" action="<?= site_url('sports') ?>" class="modal-card"><?= csrf_field() ?><div class="modal-head"><h2>Add Sport</h2><button type="button" data-close aria-label="Close"><?= ui_icon('x') ?></button></div><label>Category<select name="category" required><option value="">Select category</option><option>Men</option><option>Women</option><option>Mixed</option></select></label><label>Sport Name<input name="name" required maxlength="120" placeholder="e.g. Basketball"></label><label>Sport Type<select name="result_type" required><option value="match">Match</option><option value="judged">Judged</option></select></label><button class="btn primary full"><?= ui_icon('save') ?><span>Save Sport</span></button></form></dialog>
